import { z } from 'zod';
import { getChannelVideos } from '../lib/innertube.js';
import { DEFAULTS } from '../config.js';
import { getConfig } from '../lib/user-config.js';

export const channelVideosInputSchema = {
  channelUrl: z.string().describe('@handle, full YouTube URL, or channel ID'),
  limit: z.number().min(1).max(DEFAULTS.channel.maxVideoLimit).optional()
    .describe(`Max videos to return (default: ${DEFAULTS.channel.defaultVideoLimit}, max: ${DEFAULTS.channel.maxVideoLimit})`),
  sort: z.enum(['newest', 'popular', 'oldest']).optional()
    .describe(`Sort order (default: ${DEFAULTS.channel.defaultSort})`),
};

export async function handleChannelVideos(args: { channelUrl: string; limit?: number; sort?: string }) {
  const config = getConfig();
  const limit = args.limit ?? config.channel.defaultVideoLimit;
  const sort = args.sort ?? config.channel.defaultSort;

  const result = await getChannelVideos(args.channelUrl, limit, sort);

  return {
    content: [{
      type: 'text' as const,
      text: JSON.stringify(result, null, 2),
    }],
  };
}

import { z } from 'zod';
import { downloadVideo } from '../lib/download.js';
import { getConfig } from '../lib/user-config.js';
import type { DownloadQuality, DownloadType } from '../config.js';

export const downloadInputSchema = {
  videoId: z.string().describe('YouTube video ID'),
  outputPath: z.string().optional()
    .describe('Output file path (defaults to <title>.<format> in current directory)'),
  quality: z.enum(['best', 'bestefficiency', '144p', '240p', '360p', '480p', '720p', '1080p', '1440p', '2160p']).optional()
    .describe('Video quality (default: best)'),
  type: z.enum(['video+audio', 'audio', 'video']).optional()
    .describe('Download type — "video+audio" (default), "audio" (audio only), or "video" (no audio)'),
  format: z.string().optional()
    .describe('Container format (default: mp4)'),
  force: z.boolean().optional()
    .describe('Bypass the duration guard for long videos'),
};

interface DownloadArgs {
  videoId: string;
  outputPath?: string;
  quality?: DownloadQuality;
  type?: DownloadType;
  format?: string;
  force?: boolean;
}

export async function handleDownload(args: DownloadArgs) {
  const config = getConfig();

  const result = await downloadVideo(args.videoId, {
    quality: args.quality ?? config.download.defaultQuality,
    type: args.type ?? config.download.defaultType,
    format: args.format ?? config.download.defaultFormat,
    outputPath: args.outputPath,
    force: args.force,
  });

  return {
    content: [{
      type: 'text' as const,
      text: JSON.stringify(result, null, 2),
    }],
  };
}

import { z } from 'zod';
import { getVideoInfo, type VideoInfo } from '../lib/innertube.js';

export const videoInfoInputSchema = {
  videoId: z.string().describe('YouTube video ID'),
  detail: z.enum(['brief', 'standard', 'full']).optional()
    .describe('Detail level — "brief" (key metadata only), "standard" (most fields, truncated description, no chapters), or "full" (everything). Default: standard'),
};

type DetailLevel = 'brief' | 'standard' | 'full';

const BRIEF_FIELDS: (keyof VideoInfo)[] = [
  'id', 'title', 'channel', 'channelId', 'views', 'likes',
  'duration', 'published', 'relativeDate', 'category',
];

const DESC_TRUNCATE_LENGTH = 200;

function shapeResponse(info: VideoInfo, detail: DetailLevel): Partial<VideoInfo> {
  if (detail === 'full') return info;

  if (detail === 'brief') {
    const result: Partial<VideoInfo> = {};
    for (const key of BRIEF_FIELDS) {
      (result as any)[key] = info[key];
    }
    return result;
  }

  const { chapters, tags, thumbnail, ...rest } = info;
  return {
    ...rest,
    description: info.description.length > DESC_TRUNCATE_LENGTH
      ? info.description.slice(0, DESC_TRUNCATE_LENGTH) + '…'
      : info.description,
    chapterCount: chapters.length,
  } as any;
}

export async function handleVideoInfo(args: { videoId: string; detail?: DetailLevel }) {
  const info = await getVideoInfo(args.videoId);
  const detail = args.detail ?? 'standard';
  const shaped = shapeResponse(info, detail);

  return {
    content: [{
      type: 'text' as const,
      text: JSON.stringify(shaped, null, 2),
    }],
  };
}

import { z } from 'zod';
import { getChannelInfo } from '../lib/innertube.js';

export const channelInfoInputSchema = {
  channelId: z.string().describe('@handle, full YouTube URL, or channel ID'),
};

export async function handleChannelInfo(args: { channelId: string }) {
  const info = await getChannelInfo(args.channelId);

  return {
    content: [{
      type: 'text' as const,
      text: JSON.stringify(info, null, 2),
    }],
